/* ==========================================================
   GLOBALSTONE — SHARED STYLESHEET
   Global Commercial Real Estate Services
   ========================================================== */

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Playfair+Display:ital,wght@0,400;0,500;0,600;0,700;1,400;1,600&display=swap');

/* --- Reset --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; font-size: 16px; }
body {
  font-family: var(--font-sans);
  color: var(--color-text);
  background: var(--color-white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
button { cursor: pointer; border: none; background: none; font: inherit; }
input, textarea { font: inherit; }

/* --- Design Tokens --- */
:root {
  --color-navy:        #0A1628;
  --color-navy-deep:   #060e1a;
  --color-navy-mid:    #0f2040;
  --color-navy-light:  #1a3060;
  --color-forest:      #003F2D;
  --color-forest-mid:  #00543c;
  --color-gold:        #C8A456;
  --color-gold-hover:  #b8933f;
  --color-gold-light:  #e8c97a;
  --color-teal:        #007777;
  --color-white:       #FFFFFF;
  --color-gray-50:     #F7F7F7;
  --color-gray-100:    #EFEFEF;
  --color-gray-200:    #E2E2E2;
  --color-gray-300:    #CCCCCC;
  --color-gray-400:    #AAAAAA;
  --color-gray-600:    #666666;
  --color-gray-700:    #444444;
  --color-gray-800:    #2A2A2A;
  --color-text:        #1A1A2E;
  --color-text-muted:  #4A5568;

  --font-serif: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --font-sans:  'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;

  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;
  --space-32: 8rem;

  --container-max: 1280px;
  --container-pad: clamp(1rem, 4vw, 2.5rem);

  --shadow-sm:  0 1px 4px rgba(0,0,0,0.08);
  --shadow-md:  0 4px 16px rgba(0,0,0,0.10);
  --shadow-lg:  0 10px 32px rgba(0,0,0,0.12);
  --shadow-xl:  0 24px 56px rgba(0,0,0,0.16);

  --radius-sm: 2px;
  --radius-md: 4px;
  --radius-lg: 8px;
  --radius-xl: 12px;

  --transition-fast: 150ms ease;
  --transition-base: 260ms ease;
  --transition-slow: 420ms cubic-bezier(0.4, 0, 0.2, 1);

  --header-h: 72px;
}

/* --- Container --- */
.container {
  max-width: var(--container-max);
  margin: 0 auto;
  padding-inline: var(--container-pad);
}

/* ==========================================================
   TYPOGRAPHY
   ========================================================== */
.display {
  font-family: var(--font-serif);
  font-size: clamp(2.25rem, 5.5vw, 4rem);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.02em;
}
.h1 {
  font-family: var(--font-serif);
  font-size: clamp(1.875rem, 4.5vw, 3.25rem);
  font-weight: 600;
  line-height: 1.15;
  letter-spacing: -0.015em;
}
.h2 {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3.5vw, 2.5rem);
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: -0.01em;
}
.h3 {
  font-family: var(--font-serif);
  font-size: clamp(1.25rem, 2.5vw, 1.75rem);
  font-weight: 600;
  line-height: 1.25;
}
.h4 {
  font-family: var(--font-sans);
  font-size: 1.125rem;
  font-weight: 600;
  line-height: 1.35;
}
.eyebrow {
  font-family: var(--font-sans);
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}
.body-xl { font-size: 1.25rem; line-height: 1.65; }
.body-lg { font-size: 1.0625rem; line-height: 1.7; }
.body    { font-size: 1rem;     line-height: 1.65; }
.body-sm { font-size: 0.875rem; line-height: 1.6; }
.caption { font-size: 0.75rem;  line-height: 1.5; }

/* ==========================================================
   BUTTONS
   ========================================================== */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem 1.75rem;
  font-family: var(--font-sans);
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  border-radius: var(--radius-sm);
  transition: all var(--transition-base);
  white-space: nowrap;
  line-height: 1;
}
.btn-primary {
  background: var(--color-gold);
  color: var(--color-navy);
  box-shadow: 0 2px 8px rgba(200,164,86,0.3);
}
.btn-primary:hover {
  background: var(--color-gold-hover);
  transform: translateY(-1px);
  box-shadow: 0 4px 16px rgba(200,164,86,0.4);
}
.btn-outline-light {
  border: 1.5px solid rgba(255,255,255,0.6);
  color: var(--color-white);
  background: transparent;
}
.btn-outline-light:hover {
  background: rgba(255,255,255,0.1);
  border-color: var(--color-white);
}
.btn-outline-dark {
  border: 1.5px solid var(--color-navy);
  color: var(--color-navy);
  background: transparent;
}
.btn-outline-dark:hover {
  background: var(--color-navy);
  color: var(--color-white);
}
.btn-sm {
  padding: 0.5rem 1.25rem;
  font-size: 0.75rem;
}

.link-arrow {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--color-gold);
  transition: gap var(--transition-fast), color var(--transition-fast);
}
.link-arrow::after { content: '→'; transition: transform var(--transition-fast); }
.link-arrow:hover { gap: 0.6rem; }
.link-arrow:hover::after { transform: translateX(2px); }

.link-arrow-dark {
  color: var(--color-navy);
}
.link-arrow-dark:hover { color: var(--color-gold); }

/* ==========================================================
   HEADER & NAVIGATION
   ========================================================== */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  height: var(--header-h);
  background: var(--color-navy);
  border-bottom: 1px solid rgba(255,255,255,0.06);
  transition: box-shadow var(--transition-base);
}
.site-header.scrolled {
  box-shadow: 0 4px 24px rgba(0,0,0,0.4);
}

.header-inner {
  height: var(--header-h);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-6);
}

/* Logo */
.site-logo {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  color: var(--color-white);
  font-family: var(--font-serif);
  font-size: 1.375rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  flex-shrink: 0;
  text-decoration: none;
}
.site-logo-mark {
  width: 38px;
  height: 38px;
  background: var(--color-gold);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.875rem;
  font-weight: 800;
  color: var(--color-navy);
  border-radius: var(--radius-sm);
  letter-spacing: 0;
  flex-shrink: 0;
}

/* Primary Nav */
.primary-nav {
  display: flex;
  align-items: center;
  flex: 1;
  justify-content: center;
}
.primary-nav-list {
  display: flex;
  align-items: center;
}
.nav-item { position: relative; }
.nav-link {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0 0.875rem;
  height: var(--header-h);
  font-size: 0.8125rem;
  font-weight: 500;
  color: rgba(255,255,255,0.78);
  transition: color var(--transition-fast);
  white-space: nowrap;
  letter-spacing: 0.01em;
}
.nav-link:hover,
.nav-link.active { color: var(--color-white); }
.nav-caret {
  font-size: 0.5rem;
  transition: transform var(--transition-fast);
  opacity: 0.7;
}
.nav-item.open .nav-caret { transform: rotate(180deg); }

/* Mega Menu */
.mega-menu {
  position: absolute;
  top: var(--header-h);
  left: 50%;
  transform: translateX(-50%);
  width: 560px;
  background: var(--color-white);
  box-shadow: var(--shadow-xl);
  border-top: 3px solid var(--color-gold);
  padding: var(--space-6) var(--space-8);
  opacity: 0;
  visibility: hidden;
  transition: opacity var(--transition-base), visibility var(--transition-base), transform var(--transition-base);
  transform: translateX(-50%) translateY(-8px);
  pointer-events: none;
}
.mega-menu.open {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateX(-50%) translateY(0);
}
.mega-menu-inner {
  display: grid;
  grid-template-columns: 3fr 2fr;
  gap: var(--space-8);
}
.mega-menu-heading {
  font-size: 0.625rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--color-gray-400);
  margin-bottom: var(--space-3);
  padding-bottom: var(--space-2);
  border-bottom: 1px solid var(--color-gray-100);
}
.mega-menu-links {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.mega-menu-links a {
  display: block;
  padding: 0.4375rem 0.625rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-text);
  border-radius: var(--radius-sm);
  transition: background var(--transition-fast), color var(--transition-fast), padding-left var(--transition-fast);
}
.mega-menu-links a:hover {
  background: var(--color-gray-50);
  color: var(--color-navy);
  padding-left: 0.875rem;
}
.mega-menu-links a.highlight { color: var(--color-forest); font-weight: 600; }

/* Header Right */
.header-actions {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  flex-shrink: 0;
}
.header-search-btn {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,0.7);
  transition: color var(--transition-fast);
  border-radius: var(--radius-md);
}
.header-search-btn:hover { color: var(--color-white); }

/* Mobile Toggle */
.mobile-menu-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: var(--space-2);
  cursor: pointer;
  color: var(--color-white);
}
.mobile-menu-toggle span {
  display: block;
  width: 22px;
  height: 1.5px;
  background: currentColor;
  transition: all var(--transition-base);
  border-radius: 1px;
}
.mobile-menu-toggle.open span:nth-child(1) { transform: translateY(6.5px) rotate(45deg); }
.mobile-menu-toggle.open span:nth-child(2) { opacity: 0; transform: scaleX(0); }
.mobile-menu-toggle.open span:nth-child(3) { transform: translateY(-6.5px) rotate(-45deg); }

/* Mobile Nav Overlay */
.mobile-nav-overlay {
  display: none;
  position: fixed;
  top: var(--header-h);
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--color-navy-deep);
  overflow-y: auto;
  z-index: 999;
  padding: var(--space-4) var(--space-6) var(--space-8);
  transform: translateX(100%);
  transition: transform var(--transition-slow);
}
.mobile-nav-overlay.open { transform: translateX(0); }
.mobile-nav-item { border-bottom: 1px solid rgba(255,255,255,0.08); }
.mobile-nav-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 0;
  font-size: 0.9375rem;
  font-weight: 500;
  color: rgba(255,255,255,0.88);
  cursor: pointer;
  transition: color var(--transition-fast);
}
.mobile-nav-trigger:hover { color: var(--color-gold); }
.mobile-nav-trigger > a { flex: 1; }
.mobile-accordion-icon {
  font-size: 1.125rem;
  line-height: 1;
  color: rgba(255,255,255,0.4);
  transition: transform var(--transition-base), color var(--transition-base);
  padding: 0 0.5rem;
  user-select: none;
}
.mobile-nav-item.open .mobile-accordion-icon {
  transform: rotate(45deg);
  color: var(--color-gold);
}
.mobile-sub-nav {
  display: none;
  flex-direction: column;
  padding-bottom: var(--space-3);
}
.mobile-nav-item.open .mobile-sub-nav { display: flex; }
.mobile-sub-heading {
  font-size: 0.625rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--color-gold);
  margin-top: var(--space-4);
  margin-bottom: var(--space-2);
  padding: 0 var(--space-3);
}
.mobile-sub-nav a {
  padding: 0.4375rem var(--space-3);
  font-size: 0.875rem;
  color: rgba(255,255,255,0.65);
  transition: color var(--transition-fast), padding-left var(--transition-fast);
  border-radius: var(--radius-sm);
}
.mobile-sub-nav a:hover {
  color: var(--color-white);
  padding-left: 1.125rem;
}

/* ==========================================================
   HERO
   ========================================================== */
.hero {
  min-height: 82vh;
  display: flex;
  align-items: flex-end;
  padding-top: var(--header-h);
  padding-bottom: var(--space-20);
  position: relative;
  overflow: hidden;
}
.hero-bg {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(155deg,
      var(--color-navy) 0%,
      #0d2040 35%,
      var(--color-forest) 80%,
      #002518 100%
    );
}
.hero-bg-pattern {
  position: absolute;
  inset: 0;
  opacity: 0.04;
  background-image:
    linear-gradient(rgba(255,255,255,0.5) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.5) 1px, transparent 1px);
  background-size: 60px 60px;
}
.hero-bg-glow {
  position: absolute;
  bottom: -200px;
  right: -100px;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(200,164,86,0.08) 0%, transparent 70%);
  pointer-events: none;
}
.hero-bg-fade {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 220px;
  background: linear-gradient(to top, var(--color-navy) 0%, transparent 100%);
}
.hero-skyline {
  position: absolute;
  bottom: 0;
  right: 0;
  width: 55%;
  height: 75%;
  opacity: 0.07;
}
.hero-content {
  position: relative;
  z-index: 1;
  max-width: 760px;
}
.hero-eyebrow {
  color: var(--color-gold);
  margin-bottom: var(--space-4);
  display: flex;
  align-items: center;
  gap: var(--space-3);
}
.hero-eyebrow::before {
  content: '';
  display: block;
  width: 32px;
  height: 2px;
  background: var(--color-gold);
  flex-shrink: 0;
}
.hero-title {
  color: var(--color-white);
  margin-bottom: var(--space-6);
}
.hero-subtitle {
  color: rgba(255,255,255,0.75);
  font-size: 1.0625rem;
  line-height: 1.7;
  margin-bottom: var(--space-8);
  max-width: 580px;
}
.hero-actions {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  flex-wrap: wrap;
}

/* Hero — smaller variant for inner pages */
.hero-inner {
  min-height: 44vh;
  align-items: flex-end;
  padding-bottom: var(--space-16);
}
.hero-inner .hero-bg {
  background: linear-gradient(148deg,
    var(--color-navy) 0%,
    #0e2038 40%,
    var(--color-forest) 100%
  );
}

/* ==========================================================
   ANNOUNCEMENT BANNER
   ========================================================== */
.announcement-banner {
  background: var(--color-navy-mid);
  border-bottom: 1px solid rgba(200,164,86,0.25);
  padding: 0.75rem var(--container-pad);
}
.announcement-banner-inner {
  max-width: var(--container-max);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-4);
  text-align: center;
  flex-wrap: wrap;
}
.announcement-label {
  background: var(--color-gold);
  color: var(--color-navy);
  font-size: 0.625rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 0.2rem 0.5rem;
  border-radius: var(--radius-sm);
  flex-shrink: 0;
}
.announcement-text {
  font-size: 0.875rem;
  font-weight: 500;
  color: rgba(255,255,255,0.9);
}
.announcement-link {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--color-gold);
  white-space: nowrap;
  transition: color var(--transition-fast);
}
.announcement-link::after { content: ' →'; }
.announcement-link:hover { color: var(--color-gold-light); }
.announcement-close {
  position: absolute;
  right: var(--container-pad);
  font-size: 1rem;
  color: rgba(255,255,255,0.4);
  cursor: pointer;
  transition: color var(--transition-fast);
}
.announcement-close:hover { color: var(--color-white); }

/* ==========================================================
   SECTIONS — BASE
   ========================================================== */
.section       { padding-block: var(--space-20); }
.section-sm    { padding-block: var(--space-12); }
.section-lg    { padding-block: var(--space-32); }
.section-dark  { background: var(--color-navy);     color: var(--color-white); }
.section-mid   { background: var(--color-navy-mid); color: var(--color-white); }
.section-gray  { background: var(--color-gray-50); }
.section-white { background: var(--color-white); }

.section-header { margin-bottom: var(--space-12); }
.section-header-row {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: var(--space-8);
  margin-bottom: var(--space-12);
  flex-wrap: wrap;
}
.section-eyebrow { color: var(--color-gold); margin-bottom: var(--space-3); }
.section-title   { color: var(--color-navy); }
.section-dark .section-title { color: var(--color-white); }
.section-mid  .section-title { color: var(--color-white); }
.section-desc {
  color: var(--color-gray-600);
  max-width: 560px;
  margin-top: var(--space-4);
  font-size: 1rem;
  line-height: 1.7;
}
.section-dark .section-desc,
.section-mid  .section-desc { color: rgba(255,255,255,0.65); }

/* ==========================================================
   CARDS
   ========================================================== */
/* Insight / Article Card */
.insight-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: box-shadow var(--transition-base), transform var(--transition-base);
  display: flex;
  flex-direction: column;
}
.insight-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-3px);
}
.insight-card-img {
  height: 192px;
  background: linear-gradient(135deg, var(--color-navy) 0%, var(--color-forest) 100%);
  position: relative;
  overflow: hidden;
  flex-shrink: 0;
}
.insight-card-img-1 { background: linear-gradient(135deg, #0A1628 0%, #1e3a62 60%, #0d2a4a 100%); }
.insight-card-img-2 { background: linear-gradient(135deg, #003F2D 0%, #006040 60%, #1a3520 100%); }
.insight-card-img-3 { background: linear-gradient(135deg, #1a2840 0%, #003F2D 80%, #001a14 100%); }
.insight-card-img::after {
  content: '';
  position: absolute;
  inset: 0;
  background: url("data:image/svg+xml,%3Csvg width='80' height='80' viewBox='0 0 80 80' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.04'%3E%3Cpath d='M0 0h40v40H0V0zm40 40h40v40H40V40zm0-40h2l-2 2V0zm0 4l4-4h2l-6 6V4zm0 4l8-8h2L40 10V8zm0 4L52 0h2L40 14v-2zm0 4L56 0h2L40 18v-2zm0 4L60 0h2L40 22v-2zm0 4L64 0h2L40 26v-2zm0 4L68 0h2L40 30v-2zm0 4L72 0h2L40 34v-2zm0 4L76 0h2L40 38v-2zm0 4L80 0v2L42 40h-2zm4 0L80 4v2L46 40h-2zm4 0L80 8v2L50 40h-2zm4 0L80 12v2L54 40h-2zm4 0L80 16v2L58 40h-2zm4 0L80 20v2L62 40h-2zm4 0L80 24v2L66 40h-2zm4 0L80 28v2L70 40h-2zm4 0L80 32v2L74 40h-2zm4 0L80 36v2L78 40h-2zm4 0L80 40h-2z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
}
.insight-card-body {
  padding: var(--space-5) var(--space-6);
  display: flex;
  flex-direction: column;
  flex: 1;
}
.insight-card-tag {
  font-size: 0.625rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--color-teal);
  margin-bottom: var(--space-2);
}
.insight-card-title {
  font-family: var(--font-serif);
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--color-text);
  line-height: 1.35;
  margin-bottom: var(--space-3);
  flex: 1;
}
.insight-card-date {
  font-size: 0.75rem;
  color: var(--color-gray-400);
  margin-bottom: var(--space-4);
}

/* Featured Insight (large) */
.insight-card-featured .insight-card-img { height: 280px; }
.insight-card-featured .insight-card-title { font-size: 1.25rem; }

/* Service Card */
.service-card {
  padding: var(--space-8);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  background: var(--color-white);
  transition: all var(--transition-base);
  position: relative;
  display: flex;
  flex-direction: column;
}
.service-card::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--color-gold);
  border-radius: 0 0 var(--radius-lg) var(--radius-lg);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--transition-base);
}
.service-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-3px);
}
.service-card:hover::after { transform: scaleX(1); }
.service-card-number {
  font-family: var(--font-serif);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-gray-100);
  line-height: 1;
  margin-bottom: var(--space-4);
  transition: color var(--transition-base);
}
.service-card:hover .service-card-number { color: rgba(200,164,86,0.2); }
.service-card-title {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--color-text);
  margin-bottom: var(--space-3);
  line-height: 1.3;
}
.service-card-desc {
  font-size: 0.875rem;
  color: var(--color-gray-600);
  line-height: 1.65;
  margin-bottom: var(--space-5);
  flex: 1;
}

/* Capability Card */
.capability-card {
  padding: var(--space-6);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  background: var(--color-white);
  transition: box-shadow var(--transition-base), border-color var(--transition-base);
}
.capability-card:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--color-gold);
}
.capability-card-title {
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text);
  margin-bottom: var(--space-1);
  padding-bottom: var(--space-3);
  border-bottom: 2px solid var(--color-gold);
}
.capability-card-desc {
  font-size: 0.875rem;
  color: var(--color-gray-600);
  line-height: 1.65;
  margin-top: var(--space-3);
}

/* Commitment Card */
.commitment-card {
  padding: var(--space-8) var(--space-6);
  border-top: 3px solid var(--color-gold);
  background: var(--color-white);
}
.commitment-card-title {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--color-navy);
  margin-bottom: var(--space-4);
  margin-top: var(--space-4);
}
.commitment-card-desc {
  font-size: 0.875rem;
  color: var(--color-gray-600);
  line-height: 1.7;
  margin-bottom: var(--space-5);
}

/* ==========================================================
   GRIDS
   ========================================================== */
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: var(--space-6); }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--space-6); }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--space-6); }
.grid-6 { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--space-6); }

/* ==========================================================
   ABOUT STATEMENT
   ========================================================== */
.about-statement { background: var(--color-gray-50); }
.about-statement-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-20);
  align-items: center;
}
.about-label {
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--color-gold);
  margin-bottom: var(--space-5);
  display: flex;
  align-items: center;
  gap: var(--space-3);
}
.about-label::before {
  content: '';
  width: 28px;
  height: 2px;
  background: var(--color-gold);
}
.about-text {
  font-family: var(--font-serif);
  font-size: clamp(1.25rem, 2.5vw, 1.75rem);
  font-weight: 600;
  color: var(--color-navy);
  line-height: 1.45;
  margin-bottom: var(--space-6);
}
.about-visual {
  height: 360px;
  background: linear-gradient(155deg, var(--color-navy) 0%, #0d2040 40%, var(--color-forest) 100%);
  border-radius: var(--radius-xl);
  position: relative;
  overflow: hidden;
}
.about-visual-pattern {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(255,255,255,0.06) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.06) 1px, transparent 1px);
  background-size: 48px 48px;
}
.about-stats {
  position: absolute;
  bottom: var(--space-8);
  left: var(--space-8);
  right: var(--space-8);
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-6);
}
.about-stat-number {
  font-family: var(--font-serif);
  font-size: 2.25rem;
  font-weight: 700;
  color: var(--color-gold);
  line-height: 1;
}
.about-stat-label {
  font-size: 0.75rem;
  color: rgba(255,255,255,0.7);
  margin-top: 0.25rem;
  line-height: 1.4;
}

/* ==========================================================
   WHAT WE DO TABS
   ========================================================== */
.what-we-do-wrap {
  display: grid;
  grid-template-columns: 260px 1fr;
  min-height: 380px;
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
}
.tab-list {
  background: var(--color-gray-50);
  border-right: 1px solid var(--color-gray-200);
}
.tab-btn {
  display: block;
  width: 100%;
  padding: var(--space-5) var(--space-6);
  text-align: left;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-gray-600);
  border-left: 3px solid transparent;
  border-bottom: 1px solid var(--color-gray-200);
  transition: all var(--transition-fast);
  cursor: pointer;
  background: none;
  border-top: none;
  border-right: none;
  line-height: 1.4;
}
.tab-btn:last-child { border-bottom: none; }
.tab-btn:hover {
  color: var(--color-navy);
  background: rgba(255,255,255,0.7);
}
.tab-btn.active {
  color: var(--color-navy);
  font-weight: 600;
  border-left-color: var(--color-gold);
  background: var(--color-white);
}
.tab-panels { padding: var(--space-10) var(--space-12); }
.tab-panel { display: none; animation: fadeIn 0.3s ease; }
.tab-panel.active { display: block; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
.tab-panel-eyebrow { color: var(--color-gold); margin-bottom: var(--space-4); }
.tab-panel-title {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3vw, 2.125rem);
  font-weight: 600;
  color: var(--color-navy);
  margin-bottom: var(--space-5);
  line-height: 1.25;
}
.tab-panel-desc {
  color: var(--color-gray-600);
  font-size: 1rem;
  line-height: 1.75;
  margin-bottom: var(--space-7);
  max-width: 520px;
}

/* ==========================================================
   NEWSLETTER
   ========================================================== */
.newsletter-section {
  background: var(--color-navy-mid);
  padding: var(--space-16) 0;
  position: relative;
  overflow: hidden;
}
.newsletter-section::before {
  content: '';
  position: absolute;
  top: -100px;
  right: -100px;
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, rgba(200,164,86,0.06) 0%, transparent 70%);
}
.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr 380px;
  align-items: center;
  gap: var(--space-16);
}
.newsletter-title {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3vw, 2.125rem);
  color: var(--color-white);
  margin-bottom: var(--space-3);
}
.newsletter-desc { color: rgba(255,255,255,0.65); font-size: 1rem; line-height: 1.6; }
.newsletter-form { display: flex; gap: var(--space-3); }
.newsletter-input {
  flex: 1;
  padding: 0.8125rem 1rem;
  font-family: var(--font-sans);
  font-size: 0.875rem;
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.2);
  color: var(--color-white);
  border-radius: var(--radius-sm);
  outline: none;
  transition: border-color var(--transition-fast), background var(--transition-fast);
}
.newsletter-input::placeholder { color: rgba(255,255,255,0.4); }
.newsletter-input:focus {
  border-color: var(--color-gold);
  background: rgba(255,255,255,0.12);
}

/* ==========================================================
   FEATURED INSIGHTS GRID (homepage)
   ========================================================== */
.featured-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr;
  gap: var(--space-6);
}

/* ==========================================================
   DEAL CTA BLOCK
   ========================================================== */
.deal-cta {
  background: var(--color-navy);
  padding: var(--space-10) var(--space-12);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-8);
  position: relative;
  overflow: hidden;
}
.deal-cta::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, var(--color-gold), var(--color-gold-light), var(--color-gold));
}
.deal-cta-title {
  font-family: var(--font-serif);
  font-size: 1.75rem;
  color: var(--color-white);
  margin-bottom: var(--space-2);
}
.deal-cta-desc { color: rgba(255,255,255,0.65); font-size: 0.9375rem; }

/* ==========================================================
   TESTIMONIAL
   ========================================================== */
.testimonial-block {
  background: var(--color-navy-deep);
  padding: var(--space-10) var(--space-12);
  border-radius: var(--radius-lg);
  border-left: 4px solid var(--color-gold);
  position: relative;
}
.testimonial-quote-mark {
  font-family: var(--font-serif);
  font-size: 6rem;
  color: rgba(200,164,86,0.2);
  line-height: 0.7;
  margin-bottom: var(--space-4);
  display: block;
  font-weight: 700;
}
.testimonial-text {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  color: rgba(255,255,255,0.9);
  line-height: 1.6;
  font-style: italic;
  margin-bottom: var(--space-6);
}
.testimonial-author {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-white);
}
.testimonial-role { font-size: 0.8125rem; color: rgba(255,255,255,0.5); margin-top: 0.2rem; }

/* ==========================================================
   FEATURED TOPICS SIDEBAR
   ========================================================== */
.featured-topics-block {
  background: var(--color-gray-50);
  padding: var(--space-6);
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-gray-200);
}
.featured-topics-heading {
  font-size: 0.625rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--color-gold);
  margin-bottom: var(--space-4);
  padding-bottom: var(--space-3);
  border-bottom: 1px solid var(--color-gray-200);
}
.featured-topic-link {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-3) 0;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-text);
  border-bottom: 1px solid var(--color-gray-200);
  transition: color var(--transition-fast), gap var(--transition-fast);
}
.featured-topic-link:last-child { border-bottom: none; }
.featured-topic-link::before {
  content: '→';
  color: var(--color-gold);
  font-size: 0.8125rem;
  flex-shrink: 0;
  transition: transform var(--transition-fast);
}
.featured-topic-link:hover { color: var(--color-gold); }
.featured-topic-link:hover::before { transform: translateX(4px); }

/* ==========================================================
   PARTNERSHIP HIGHLIGHT
   ========================================================== */
.partnership-highlight {
  background: linear-gradient(145deg, var(--color-navy) 0%, var(--color-forest) 100%);
  color: var(--color-white);
  padding: var(--space-12) var(--space-16);
  border-radius: var(--radius-xl);
  position: relative;
  overflow: hidden;
}
.partnership-highlight::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(255,255,255,0.04) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.04) 1px, transparent 1px);
  background-size: 40px 40px;
}
.partnership-inner { position: relative; }
.partnership-quote-mark {
  font-family: var(--font-serif);
  font-size: 7rem;
  line-height: 0.6;
  color: rgba(200,164,86,0.2);
  font-weight: 700;
  display: block;
  margin-bottom: var(--space-4);
}
.partnership-text {
  font-family: var(--font-serif);
  font-size: clamp(1.125rem, 2vw, 1.5rem);
  line-height: 1.55;
  color: rgba(255,255,255,0.9);
  max-width: 680px;
  margin-bottom: var(--space-10);
}
.partnership-stats {
  display: flex;
  gap: var(--space-12);
  padding-top: var(--space-8);
  border-top: 1px solid rgba(255,255,255,0.12);
}
.partnership-stat-num {
  font-family: var(--font-serif);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-gold);
  line-height: 1;
}
.partnership-stat-label {
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.6);
  margin-top: var(--space-1);
  max-width: 160px;
  line-height: 1.4;
}

/* ==========================================================
   CAROUSEL
   ========================================================== */
.carousel { position: relative; overflow: hidden; }
.carousel-track {
  display: flex;
  transition: transform var(--transition-slow);
}
.carousel-slide { flex: 0 0 100%; }
.carousel-controls {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  margin-top: var(--space-6);
}
.carousel-btn {
  width: 44px;
  height: 44px;
  border: 1.5px solid var(--color-gray-200);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.125rem;
  color: var(--color-navy);
  cursor: pointer;
  transition: all var(--transition-fast);
  background: var(--color-white);
}
.carousel-btn:hover {
  background: var(--color-navy);
  color: var(--color-white);
  border-color: var(--color-navy);
}
.carousel-dots { display: flex; gap: var(--space-2); align-items: center; }
.carousel-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--color-gray-300);
  cursor: pointer;
  transition: all var(--transition-fast);
}
.carousel-dot.active {
  background: var(--color-navy);
  width: 20px;
  border-radius: 3px;
}

/* Partner Card (inside carousel) */
.partner-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  display: grid;
  grid-template-columns: 120px 1fr;
  gap: var(--space-8);
  align-items: center;
}
.partner-logo {
  width: 120px;
  height: 80px;
  background: var(--color-gray-100);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-gray-400);
}
.partner-content-title {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--color-navy);
  margin-bottom: var(--space-3);
}
.partner-content-desc {
  font-size: 0.9375rem;
  color: var(--color-gray-600);
  line-height: 1.65;
}

/* ==========================================================
   PROPERTY TYPES CTA
   ========================================================== */
.property-types-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-4);
}
.property-type-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: var(--space-6) var(--space-4);
  text-align: center;
  transition: all var(--transition-base);
  cursor: pointer;
}
.property-type-card:hover {
  border-color: var(--color-gold);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}
.property-type-icon {
  font-size: 2rem;
  margin-bottom: var(--space-3);
  display: block;
}
.property-type-label {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--color-text);
}

/* ==========================================================
   RELATED SERVICES / INSIGHTS
   ========================================================== */
.related-service-card {
  padding: var(--space-5) var(--space-6);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  background: var(--color-white);
  transition: all var(--transition-base);
  display: flex;
  align-items: flex-start;
  gap: var(--space-4);
}
.related-service-card:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--color-gold);
}
.related-service-dot {
  width: 8px;
  height: 8px;
  background: var(--color-gold);
  border-radius: 50%;
  margin-top: 6px;
  flex-shrink: 0;
}
.related-service-title {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--color-navy);
  margin-bottom: var(--space-1);
}
.related-service-desc {
  font-size: 0.8125rem;
  color: var(--color-gray-600);
  line-height: 1.5;
}

/* ==========================================================
   INTRO STATEMENT BANNER
   ========================================================== */
.intro-statement {
  background: var(--color-gray-50);
  padding: var(--space-12) 0;
  border-bottom: 1px solid var(--color-gray-200);
}
.intro-text {
  font-family: var(--font-serif);
  font-size: clamp(1.125rem, 2.5vw, 1.5rem);
  color: var(--color-navy);
  line-height: 1.6;
  max-width: 880px;
}

/* ==========================================================
   FOOTER
   ========================================================== */
.site-footer {
  background: var(--color-navy-deep);
  color: rgba(255,255,255,0.65);
}
.footer-top {
  display: grid;
  grid-template-columns: 2.2fr 1fr 1fr 1fr 1fr;
  gap: var(--space-10);
  padding: var(--space-16) 0 var(--space-12);
  border-bottom: 1px solid rgba(255,255,255,0.08);
}
.footer-brand-name {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-white);
  margin-bottom: var(--space-4);
  display: flex;
  align-items: center;
  gap: var(--space-3);
}
.footer-brand-mark {
  width: 32px;
  height: 32px;
  background: var(--color-gold);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 800;
  color: var(--color-navy);
}
.footer-tagline {
  font-size: 0.875rem;
  line-height: 1.65;
  margin-bottom: var(--space-6);
  max-width: 280px;
}
.footer-col-heading {
  font-size: 0.625rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--color-white);
  margin-bottom: var(--space-4);
}
.footer-links { display: flex; flex-direction: column; gap: 0.4375rem; }
.footer-links a {
  font-size: 0.875rem;
  color: rgba(255,255,255,0.55);
  transition: color var(--transition-fast);
  line-height: 1.5;
}
.footer-links a:hover { color: var(--color-gold); }
.footer-bottom {
  padding: var(--space-5) 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-4);
  flex-wrap: wrap;
}
.footer-legal { font-size: 0.75rem; color: rgba(255,255,255,0.35); }
.footer-legal-links {
  display: flex;
  gap: var(--space-6);
  flex-wrap: wrap;
}
.footer-legal-links a {
  font-size: 0.75rem;
  color: rgba(255,255,255,0.35);
  transition: color var(--transition-fast);
}
.footer-legal-links a:hover { color: rgba(255,255,255,0.7); }

/* Social Icons */
.footer-social {
  display: flex;
  gap: var(--space-3);
  margin-top: var(--space-4);
}
.social-icon {
  width: 34px;
  height: 34px;
  border: 1px solid rgba(255,255,255,0.15);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  color: rgba(255,255,255,0.5);
  transition: all var(--transition-fast);
}
.social-icon:hover {
  border-color: var(--color-gold);
  color: var(--color-gold);
  background: rgba(200,164,86,0.08);
}

/* ==========================================================
   UTILITY CLASSES
   ========================================================== */
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
