/* ==========================================================
   GLOBALSTONE — NAVIGATION & INTERACTIVITY
   ========================================================== */

(function () {
  'use strict';

  document.addEventListener('DOMContentLoaded', init);

  function init() {
    setupHeader();
    setupMegaMenu();
    setupMobileNav();
    setupTabs();
    setupCarousels();
    setupAnnouncementBanner();
    setActiveNavLink();
  }

  /* ----------------------------------------------------------
     Header — scroll shadow
  ---------------------------------------------------------- */
  function setupHeader() {
    const header = document.querySelector('.site-header');
    if (!header) return;
    const onScroll = () => {
      header.classList.toggle('scrolled', window.scrollY > 20);
    };
    window.addEventListener('scroll', onScroll, { passive: true });
    onScroll();
  }

  /* ----------------------------------------------------------
     Mega Menu
  ---------------------------------------------------------- */
  function setupMegaMenu() {
    const items = document.querySelectorAll('.nav-item.has-dropdown');
    let closeTimer;

    items.forEach(item => {
      const menu = item.querySelector('.mega-menu');
      if (!menu) return;

      const open = () => {
        clearTimeout(closeTimer);
        // Close any other open menus first
        items.forEach(other => {
          if (other !== item) {
            other.classList.remove('open');
            other.querySelector('.mega-menu')?.classList.remove('open');
          }
        });
        item.classList.add('open');
        menu.classList.add('open');
      };

      const close = () => {
        closeTimer = setTimeout(() => {
          item.classList.remove('open');
          menu.classList.remove('open');
        }, 120);
      };

      item.addEventListener('mouseenter', open);
      item.addEventListener('mouseleave', close);
      menu.addEventListener('mouseenter', () => clearTimeout(closeTimer));
      menu.addEventListener('mouseleave', close);

      // Click toggle for touch / keyboard
      const link = item.querySelector('.nav-link');
      if (link) {
        link.addEventListener('click', e => {
          const isOpen = item.classList.contains('open');
          // If it has a real href (non-#), allow navigation when already open
          const href = link.getAttribute('href');
          if (href && href !== '#' && isOpen) return;
          e.preventDefault();
          isOpen ? close() : open();
        });
      }
    });

    // Close on outside click
    document.addEventListener('click', e => {
      if (!e.target.closest('.nav-item.has-dropdown')) {
        items.forEach(item => {
          item.classList.remove('open');
          item.querySelector('.mega-menu')?.classList.remove('open');
        });
      }
    });

    // ESC key
    document.addEventListener('keydown', e => {
      if (e.key === 'Escape') {
        items.forEach(item => {
          item.classList.remove('open');
          item.querySelector('.mega-menu')?.classList.remove('open');
        });
      }
    });
  }

  /* ----------------------------------------------------------
     Mobile Nav
  ---------------------------------------------------------- */
  function setupMobileNav() {
    const toggle = document.querySelector('.mobile-menu-toggle');
    const overlay = document.querySelector('.mobile-nav-overlay');
    if (!toggle || !overlay) return;

    toggle.addEventListener('click', () => {
